<?php
$u=user();$b=json_body();require_fields($b,['purpose','fileName','contentType','dataUri']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];$type=(string)$b['contentType'];if(!isset($allowed[$type]))fail(415,'UNSUPPORTED_MEDIA_TYPE','Only JPEG, PNG and WebP images are allowed.');if(!preg_match('#^data:'.preg_quote($type,'#').';base64,(.+)$#s',(string)$b['dataUri'],$m))fail(422,'VALIDATION_ERROR','The dataUri is invalid.',['dataUri'=>['Expected a complete base64 data URI.']]);$bytes=base64_decode($m[1],true);if($bytes===false)fail(422,'VALIDATION_ERROR','The image encoding is invalid.');if(strlen($bytes)>5*1024*1024)fail(413,'UPLOAD_TOO_LARGE','The maximum decoded size is 5 MiB.');$finfo=new finfo(FILEINFO_MIME_TYPE);if($finfo->buffer($bytes)!==$type)fail(415,'UNSUPPORTED_MEDIA_TYPE','The file signature does not match its declared type.');$id=uuid();$dir=dirname(__DIR__,2).'/uploads/'.$u['id'];if(!is_dir($dir)&&!mkdir($dir,0750,true))fail(500,'UPLOAD_FAILED','Could not create upload storage.');$name=$id.'.'.$allowed[$type];if(file_put_contents($dir.'/'.$name,$bytes)===false)fail(500,'UPLOAD_FAILED','Could not store the upload.');$path='uploads/'.$u['id'].'/'.$name;db()->prepare('INSERT INTO uploads(id,user_id,purpose,file_name,content_type,path,size_bytes) VALUES(?,?,?,?,?,?,?)')->execute([$id,$u['id'],$b['purpose'],$b['fileName'],$type,$path,strlen($bytes)]);out(['id'=>$id,'purpose'=>$b['purpose'],'contentType'=>$type,'sizeBytes'=>strlen($bytes),'url'=>'/'.$path],201);
